+// lib/util/validateRegex.js
+// Validates regex patterns to prevent ReDoS attacks (CVE-2025-69873)
+
+const MAX_PATTERN_LENGTH = 1000;
+const KeywordError = require("../errors");
+
+// Matches nested quantifiers: a group containing a quantifier (*, +, ?) that is itself quantified.
+// Catches patterns like (a+)+, (a*)*, (a{2,3})* etc.
+const NESTED_QUANTIFIER = /\((?:[^)(?\\]|\\.)*[+*?](?:[^)(?\\]|\\.)*\)\s*[+*?]/;
+
+/**
+ * Validates a regex pattern to ensure it is not vulnerable to ReDoS.
+ * @param {string} pattern - The regex pattern to validate.
+ * @param {object} it - The ajv instance context (for error reporting).
+ * @param {string} keyword - The keyword name (for error reporting).
+ * @throws {KeywordError} If the pattern is invalid or potentially dangerous.
+ */
+module.exports = function validateRegex(pattern, it, keyword) {
+  if (typeof pattern !== "string") {
+    throw new KeywordError(keyword, it, "Regex pattern must be a string");
+  }
+
+  if (pattern.length > MAX_PATTERN_LENGTH) {
+    throw new KeywordError(keyword, it, `Regex pattern exceeds maximum allowed length of ${MAX_PATTERN_LENGTH}`);
+  }
+
+  // Check for nested quantifiers
+  if (NESTED_QUANTIFIER.test(pattern)) {
+    throw new KeywordError(keyword, it, "Regex pattern contains nested quantifiers which may lead to ReDoS");
+  }
+
+  // Check for duplicate alternatives in quantified groups (e.g., (a|a)*)
+  const groupRegex = /\((?:[^)(?\\]|\\.)*\)/g;
+  let groupMatch;
+  while ((groupMatch = groupRegex.exec(pattern)) !== null) {
+    const group = groupMatch[0];
+    // Check if the group is followed by a quantifier
+    const isQuantified = /\)\s*[+*?]/.test(pattern.slice(groupMatch.index + groupMatch[0].length));
+    if (!isQuantified) continue;
+    // Split group into alternatives, ignoring escaped | and nested groups (simplified)
+    const alternatives = group.split(/(?<!\\)\|/).map(alt => alt.replace(/^\(|\)$/g, '').trim());
+    // Check for duplicate alternatives
+    const uniqueAlternatives = new Set(alternatives);
+    if (uniqueAlternatives.size < alternatives.length) {
+      throw new KeywordError(keyword, it, "Regex pattern contains duplicate alternatives in a quantified group which may lead to ReDoS");
+    }
+  }
+};

